package org.apache.commons.math.analysis;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for BrentSolver.solve(double, double)
 */
public class BrentSolver_solve_TriageGen2Test {

    /**
     * Mock function to control return values for testing different branches.
     */
    private static class MockFunction implements UnivariateRealFunction {
        private final double minVal;
        private final double maxVal;

        public MockFunction(double minVal, double maxVal) {
            this.minVal = minVal;
            this.maxVal = maxVal;
        }

        @Override
        public double value(double x) {
            // In a real scenario, we'd map x to specific values, 
            // but for this triage, we simulate the return based on the logic.
            // However, since the solve method calls f.value(min) and f.value(max),
            // we need a way to return different values for different inputs.
            return 0; // Placeholder
        }
    }

    /**
     * A more flexible mock to handle specific input values.
     */
    private static class FlexibleMockFunction implements UnivariateRealFunction {
        private double minVal;
        private double maxVal;

        public void setValues(double minVal, double maxVal) {
            this.minVal = minVal;
            this.maxVal = maxVal;
        }

        @Override
        public double value(double x) {
            // This is a simplification; in actual testing we'd use a Map or conditional logic
            // But for the purpose of testing the solve logic branches:
            if (x == 0.0) return minVal; // We use 0.0 as a sentinel for 'min'
            if (x == 1.0) return maxVal; // We use 1.0 as a sentinel for 'max'
            return 0;
        }
    }

    @Test
    public void testSolve_BracketedRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // sign < 0 case
        UnivariateRealFunction f = x -> x - 0.5; // f(0) = -0.5, f(1) = 0.5
        BrentSolver solver = new BrentSolver(f);
        double result = solver.solve(0.0, 1.0);
        assertEquals(0.5, result, 1e-10);
    }

    @Test
    public void testSolve_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // sign == 0 case (yMin == 0)
        UnivariateRealFunction f = x -> (x == 0.0) ? 0.0 : 1.0;
        BrentSolver solver = new BrentSolver(f);
        double result = solver.solve(0.0, 1.0);
        assertEquals(0.0, result, 1e-10);
    }

    @Test
    public void testSolve_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // sign == 0 case (yMax == 0)
        UnivariateRealFunction f = x -> (x == 1.0) ? 0.0 : 1.0;
        BrentSolver solver = new BrentSolver(f);
        double result = solver.solve(0.0, 1.0);
        assertEquals(1.0, result, 1e-10);
    }

    @Test
    public void testSolve_SignPositive_MinCloseToZero() throws MaxIterationsExceededException, FunctionEvaluationException {
        // sign > 0 case, Math.abs(yMin) <= functionValueAccuracy
        // Note: functionValueAccuracy is internal, assuming it's a small positive value like 1e-10
        double accuracy = 1e-10; 
        UnivariateRealFunction f = x -> (x == 0.0) ? accuracy / 2.0 : 1.0;
        BrentSolver solver = new BrentSolver(f);
        // We can't set accuracy directly, but we can provide a value that satisfies the condition
        double result = solver.solve(0.0, 1.0);
        assertEquals(0.0, result, 1e-10);
    }

    @Test
    public void testSolve_SignPositive_MaxBranch() throws MaxIterationsExceededException, FunctionEvaluationException {
        // sign > 0 case, enters the 'else if (true)' branch
        // In the provided code, there is an 'else if (true)' which forces this branch.
        UnivariateRealFunction f = x -> 1.0; 
        BrentSolver solver = new BrentSolver(f);
        double result = solver.solve(0.0, 1.0);
        assertEquals(1.0, result, 1e-10);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolve_VerifyInterval_Throws() throws MaxIterationsExceededException, FunctionEvaluationException {
        // This tests the verifyInterval(min, max) call which usually throws if min >= max
        UnivariateRealFunction f = x -> x;
        BrentSolver solver = new BrentSolver(f);
        solver.solve(1.0, 0.0);
    }
}
